Looking at this problem, I need to partition N distinct integers from {1,...,M} into K sets with given medians, maximizing total sum.

**Key insight**: For a set of size n with median c_i, I need l_i = ⌈n/2⌉-1 elements below c_i and r_i = n - ⌈n/2⌉ elements above. The constraint is r_i ∈ {l_i, l_i+1}. To maximize sum: use largest possible values as "above" elements, smallest as "below" elements.

**Strategy**:
- Total extra elements T = N-K. Max above = ⌊N/2⌋ (from constraint r_i ≤ l_i+1)
- K_extra groups get one extra "above" slot (r_i = l_i + 1), rest balanced
- Below pool: smallest T_below available values; Above pool: largest T_above available values
- Assign above elements greedily from groups with smallest c_i (most flexibility)
- Assign below elements from groups with smallest c_i using smallest available values < c_i

I verified with the example: gets SUM=41 same as example output.

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M, K;
    cin >> N >> M >> K;

    vector<int> c(K);
    for (int i = 0; i < K; i++) cin >> c[i];

    vector<bool> is_med(M + 1, false);
    for (int x : c) is_med[x] = true;

    vector<int> avail;
    avail.reserve(M - K);
    for (int v = 1; v <= M; v++)
        if (!is_med[v]) avail.push_back(v);
    int A = (int)avail.size();

    vector<int> order(K);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return c[a] < c[b]; });

    vector<int> sc(K);
    for (int i = 0; i < K; i++) sc[i] = c[order[i]];

    int T = N - K;
    int K_extra = min(K, T);
    if ((T - K_extra) % 2 != 0) K_extra--;
    int pairs = (T - K_extra) / 2;
    int T_above = pairs + K_extra;
    int T_below = pairs;

    vector<int> l(K), r(K);
    int base_p = (K > 0) ? pairs / K : 0;
    int rem_p = (K > 0) ? pairs % K : 0;
    for (int i = 0; i < K; i++) {
        l[i] = base_p + (i >= K - rem_p ? 1 : 0);
        r[i] = l[i];
    }
    for (int i = K - K_extra; i < K; i++) r[i]++;

    vector<vector<int>> sets(K);
    for (int i = 0; i < K; i++) sets[i].push_back(sc[i]);

    // Assign below elements
    int bptr = 0;
    for (int i = 0; i < K && bptr < T_below; i++) {
        for (int j = 0; j < l[i] && bptr < T_below; j++) {
            while (bptr < T_below && avail[bptr] >= sc[i]) bptr++;
            if (bptr < T_below) sets[i].push_back(avail[bptr++]);
        }
    }

    // Assign above elements (from groups with smallest c first for max flexibility)
    int aptr = A - 1;
    for (int i = 0; i < K && aptr >= A - T_above; i++) {
        for (int j = 0; j < r[i] && aptr >= A - T_above; j++) {
            while (aptr >= A - T_above && avail[aptr] <= sc[i]) aptr--;
            if (aptr >= A - T_above) sets[i].push_back(avail[aptr--]);
        }
    }

    // If above pointer didn't reach all groups, try reverse order for remaining
    if (aptr >= A - T_above) {
        for (int i = K - 1; i >= 0 && aptr >= A - T_above; i--) {
            while (aptr >= A - T_above && avail[aptr] <= sc[i]) aptr--;
            if (aptr >= A - T_above && (int)sets[i].size() < 1 + l[i] + r[i]) {
                sets[i].push_back(avail[aptr--]);
            }
        }
    }

    vector<int> rev(K);
    for (int i = 0; i < K; i++) rev[order[i]] = i;

    for (int i = 0; i < K; i++) {
        cout << sets[rev[i]].size();
        if (i < K - 1) cout << " ";
    }
    cout << "\n";

    for (int i = 0; i < K; i++) {
        int si = rev[i];
        sort(sets[si].begin(), sets[si].end());
        for (int j = 0; j < (int)sets[si].size(); j++) {
            cout << sets[si][j];
            if (j < (int)sets[si].size() - 1) cout << " ";
        }
        cout << "\n";
    }

    return 0;
}
