int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long N,M,K;
    cin>>N>>M>>K;
    vector<int>c(K);
    for(int i=0;i<K;i++) cin>>c[i];
    vector<int>order(K);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return c[a]>c[b];});
    vector<bool>used(M+2,false);
    for(int i=0;i<K;i++) used[c[i]]=true;
    long long T=N-K;
    // Collect non-median values
    vector<int>avail;
    avail.reserve(M-K+1);
    for(int v=1;v<=M;v++) if(!used[v]) avail.push_back(v);
    // Compute B_min
    long long B=0;
    if(T>K) B=(T-K+1)/2;
    long long A=T-B;
    // Each set gets j[i] extras distributed: first A as above (1 each round), then B as below
    // Distribute: give sets in order 0,1,...,K-1 (desc c) rounds of above, then below
    vector<long long>ai(K,0),bi(K,0);
    // Distribute A above among sets (greedily to highest c first) and B below
    // Round-robin for above: each set gets floor(A/K) or ceil(A/K)
    // But to maximize sum, concentrate above in highest-c sets
    // Actually, value assignment doesn't depend on which set gets it if feasible
    // Use: give each set same # above, excess to first sets
    long long base_a=A/K, extra_a=A%K;
    long long base_b=B/K, extra_b=B%K;
    for(int i=0;i<K;i++){
        ai[i]=base_a+(i<extra_a?1:0);
        bi[i]=base_b+(i<extra_b?1:0);
        // Enforce: ai[i] == bi[i] or bi[i]+1
        // Adjust: if ai[i]<bi[i], fix; if ai[i]>bi[i]+1, fix
    }
    // Re-distribute to satisfy ai[i] in {bi[i], bi[i]+1}
    // Simple: for each set assign j[i] extras; ai=ceil(j/2), bi=floor(j/2) when we go above first
    // j[i] extras: ai=floor((j[i]+1)/2), bi=floor(j[i]/2)
    // Distribute T extras: give highest-c sets more
    vector<long long>ji(K,0);
    long long rem=T;
    // Give as many as possible to set 0, then 1, etc. - but also need feasibility
    // Actually round-robin to all sets first (1 each), then 2 more each, etc.
    for(int i=0;i<K&&rem>0;i++,rem--) ji[i]++;
    for(long long r=0;rem>0;){
        for(int i=0;i<K&&rem>0;i++,rem--) ji[i]+=2;
    }
    for(int i=0;i<K;i++){
        ai[i]=(ji[i]+1)/2; // ceil(j/2) -- first extra is above
        bi[i]=ji[i]/2;
    }
    // Now assign actual values
    // above: take A largest non-median values; assign to sets from highest c
    // below: take B smallest non-median values; assign to sets from lowest c
    int hi=(int)avail.size()-1, lo=0;
    vector<vector<int>>sets(K);
    for(int i=0;i<K;i++) sets[i].push_back(c[order[i]]);
    // Assign below values (small) to sets that need them, from highest c downward (they have most below space)
    // Process below: assign B smallest values to sets needing below, smallest c sets get values < their c
    // We need bi[i] below values for set order[i] (sorted desc c)
    // Below values must be < c[order[i]]; smallest sets might have trouble
    // Use: collect all needed below values from bottom, assign to sets greedily
    // First collect below values
    vector<int>bvals,avals;
    // Below: B smallest non-median values that are < some c_i
    // Since sets sorted desc c, we assign below from smallest values to sets with largest c first? Or last?
    // Actually assign below to sets: set with small c needs values < c, so only small values work
    // Sort sets ascending c for below assignment
    vector<int>order2(K); iota(order2.begin(),order2.end(),0);
    sort(order2.begin(),order2.end(),[&](int a,int b){return c[order[a]]<c[order[b]];});
    // Assign below greedily: for each set from smallest c, take bi[set] smallest available < c[set]
    for(int idx=0;idx<K;idx++){
        int i=order2[idx];
        int ci=c[order[i]];
        long long need=bi[i];
        while(need>0&&lo<=(int)avail.size()-1&&avail[lo]<ci){
            sets[i].push_back(avail[lo++]); need--;
        }
        if(need>0){bi[i]-=need; ai[i]-=need;} // couldn't fill, reduce
    }
    // Assign above greedily: for each set from largest c, take ai[set] largest available > c[set]
    for(int i=0;i<K;i++){
        int ci=c[order[i]];
        long long need=ai[i];
        while(need>0&&hi>=lo&&avail[hi]>ci){
            sets[i].push_back(avail[hi--]); need--;
        }
    }
    // Output
    for(int i=0;i<K;i++){
        sort(sets[i].begin(),sets[i].end());
        if(i) cout<<' ';
        cout<<sets[i].size();
    }
    cout<<'\n';
    for(int i=0;i<K;i++){
        // sets[i] corresponds to original index order[i]
    }
    // Need to output in original order
    vector<vector<int>>res(K);
    for(int i=0;i<K;i++) res[order[i]]=sets[i];
    for(int i=0;i<K;i++){
        for(int j=0;j<(int)res[i].size();j++){
            if(j) cout<<' ';
            cout<<res[i][j];
        }
        cout<<'\n';
    }
}
