```cpp
#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N, M, K;
    cin >> N >> M >> K;

    vector<long long> c(K);
    for(int i=0;i<K;i++) cin >> c[i];

    // Sort by median value
    vector<int> ord(K);
    iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){return c[a]<c[b];});

    vector<long long> sc(K);
    for(int i=0;i<K;i++) sc[i]=c[ord[i]];

    // For each set i (sorted), max_b[i] = sc[i]-1-i (non-median values below sc[i])
    // b[i] = below count, a[i] = above count (extra, beyond the initial 1 above per set)
    vector<long long> b(K,0), a(K,0);

    long long E = N - K;
    long long remaining;

    if(E <= K){
        // Give E sets one above element each
        for(int i=0;i<K && i<E;i++) a[i]=1;
        remaining = 0;
    } else {
        // Give all sets one above
        for(int i=0;i<K;i++) a[i]=1;
        remaining = E - K;
    }

    // Now distribute 'remaining' elements as pairs (below+above) + possibly one extra below
    // To maximize sum: spread pairs to sets with largest max_b capacity first (largest sc[i])
    // Process from largest sc to smallest

    // For each pair, we give set i: b[i]++, a[i]++
    // For extra single below: b[i]++

    // Distribute pairs greedily: sets with largest capacity first
    long long pairs = remaining / 2;
    long long extra_below = remaining % 2; // 0 or 1

    // Distribute pairs from largest to smallest
    for(int i=K-1; i>=0 && pairs>0; i--){
        long long cap = max(0LL, sc[i]-1-i - b[i]); // available below capacity
        long long take = min(cap, pairs);
        b[i] += take;
        a[i] += take;
        pairs -= take;
    }

    // If pairs still remain (shouldn't happen if feasible), force it
    if(pairs > 0){
        // Distribute anyway (might violate constraints but try)
        for(int i=K-1;i>=0 && pairs>0;i--){
            b[i]+=pairs; a[i]+=pairs; pairs=0;
        }
    }

    // Distribute extra below
    if(extra_below > 0){
        for(int i=K-1;i>=0;i--){
            long long cap = max(0LL, sc[i]-1-i - b[i]);
            if(cap > 0){
                b[i]++;
                extra_below--;
                break;
            }
        }
        if(extra_below > 0){
            // fallback
            b[K-1]++;
            extra_below=0;
        }
    }

    long long total_b=0, total_a=0;
    for(int i=0;i<K;i++){total_b+=b[i]; total_a+=a[i];}

    // Build below_vals: smallest total_b non-median values
    // Build above_vals: largest total_a non-median values
    set<long long> mset(sc.begin(),sc.end());

    vector<long long> below_vals, above_vals;
    below_vals.reserve(total_b);
    above_vals.reserve(total_a);

    {
        long long cnt=0;
        for(long long v=1; v<=M && cnt<total_b; v++){
            if(!mset.count(v)){below_vals.push_back(v); cnt++;}
        }
    }
    {
        long long cnt=0;
        for(long long v=M; v>=1 && cnt<total_a; v--){
            if(!mset.count(v)){above_vals.push_back(v); cnt++;}
        }
        reverse(above_vals.begin(),above_vals.end()); // ascending
    }

    // Assign: below_vals assigned to sets in sorted order (smallest c first)
    // a[i] above elements: assign largest above to sets with largest c first

    vector<vector<long long>> result(K);
    for(int i=0;i<K;i++) result[i].push_back(sc[i]);

    // Assign below
    long long bptr=0;
    for(int i=0;i<K;i++){
        for(long long j=0;j<b[i];j++){
            result[i].push_back(below_vals[bptr++]);
        }
    }

    // Assign above: largest values to sets with largest c (they can accommodate any large value)
    // above_vals is ascending; take from end (largest) for largest c sets
    long long aptr = (long long)above_vals.size()-1;
    for(int i=K-1;i>=0;i--){
        for(long long j=0;j<a[i];j++){
            if(aptr>=0){
                result[i].push_back(above_vals[aptr--]);
            }
        }
    }

    // Sort each result set and output in original order
    vector<vector<long long>> out(K);
    for(int i=0;i<K;i++){
        out[ord[i]] = result[i];
        sort(out[ord[i]].begin(),out[ord[i]].end());
    }

    for(int i=0;i<K;i++){
        cout << out[i].size();
        if(i<K-1) cout << ' ';
    }
    cout << '\n';

    for(int i=0;i<K;i++){
        for(int j=0;j<(int)out[i].size();j++){
            cout << out[i][j];
            if(j<(int)out[i].size()-1) cout << ' ';
        }
        cout << '\n';
    }

    return 0;
}
